  "inlineSchema": "// CoalGov Prisma Schema\n// Database: PostgreSQL\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  ADMIN\n  MINE_OFFICIAL\n  INSPECTOR\n  MANAGER\n  REGULATOR\n}\n\nenum ComplianceCategory {\n  SAFETY\n  ENVIRONMENT\n  PRODUCTION\n  LABOUR\n}\n\nenum ComplianceStatus {\n  COMPLIANT\n  NON_COMPLIANT\n  UNDER_REVIEW\n  EXPIRED\n}\n\nenum InspectionStatus {\n  SCHEDULED\n  IN_PROGRESS\n  COMPLETED\n  FLAGGED\n}\n\nenum Severity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum ViolationStatus {\n  REPORTED\n  ACTION_ASSIGNED\n  RECTIFIED\n  VERIFIED\n  CLOSED\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  password     String\n  name         String\n  role         Role     @default(MINE_OFFICIAL)\n  phone        String?\n  mineName     String? // Associated mine/block name if applicable\n  designation  String? // Official designation / title\n  refreshToken String?  @db.Text\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relationships\n  inspections     Inspection[]       @relation(\"InspectorInspections\")\n  violations      Violation[]        @relation(\"ReportedViolations\")\n  actionsAssigned CorrectiveAction[] @relation(\"AssignedActions\")\n  auditLogs       AuditLog[]\n\n  @@map(\"users\")\n}\n\nmodel Mine {\n  id                String   @id @default(uuid())\n  code              String   @unique // e.g. MINE-JH-001\n  name              String\n  subsidiary        String // e.g. ECL, BCCL, CCL, WCL, SECL, MCL, NCL\n  state             String\n  district          String\n  latitude          Float?\n  longitude         Float?\n  operationalStatus String   @default(\"ACTIVE\") // ACTIVE, SUSPENDED, CLOSED\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  inspections Inspection[]\n  compliances StatutoryCompliance[]\n\n  @@map(\"mines\")\n}\n\nmodel StatutoryCompliance {\n  id          String             @id @default(uuid())\n  mineId      String\n  title       String\n  category    ComplianceCategory\n  status      ComplianceStatus   @default(UNDER_REVIEW)\n  validUntil  DateTime?\n  documentUrl String? // PDF Clearance / Statutory Certificate\n  remarks     String? // Written remarks / regulatory conditions\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n\n  mine Mine @relation(fields: [mineId], references: [id], onDelete: Cascade)\n\n  @@map(\"statutory_compliances\")\n}\n\nmodel Inspection {\n  id            String           @id @default(uuid())\n  mineId        String\n  inspectorId   String\n  title         String\n  status        InspectionStatus @default(SCHEDULED)\n  scheduledDate DateTime\n  completedDate DateTime?\n  latitude      Float? // Geo-tagging\n  longitude     Float? // Geo-tagging\n  reportUrl     String? // Official Inspection Report PDF from Authority\n  notes         String? // Written observations / notes\n  createdAt     DateTime         @default(now())\n  updatedAt     DateTime         @updatedAt\n\n  mine       Mine        @relation(fields: [mineId], references: [id], onDelete: Cascade)\n  inspector  User        @relation(\"InspectorInspections\", fields: [inspectorId], references: [id])\n  violations Violation[]\n\n  @@map(\"inspections\")\n}\n\nmodel Violation {\n  id           String             @id @default(uuid())\n  inspectionId String\n  reporterId   String\n  title        String\n  description  String // Written description of the violation\n  severity     Severity           @default(MEDIUM)\n  status       ViolationStatus    @default(REPORTED)\n  category     ComplianceCategory\n  deadline     DateTime?\n  noticePdfUrl String? // Official Violation / Show-Cause Notice PDF from Authority\n  imageUrl     String? // Photo / Image evidence\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  inspection Inspection         @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  reporter   User               @relation(\"ReportedViolations\", fields: [reporterId], references: [id])\n  actions    CorrectiveAction[]\n\n  @@map(\"violations\")\n}\n\nmodel CorrectiveAction {\n  id             String    @id @default(uuid())\n  violationId    String\n  assigneeId     String\n  actionPlan     String // Action plan details\n  responseText   String? // Mine official's written response / justification\n  responsePdfUrl String? // Mine official's formal counter / compliance response PDF\n  evidenceUrl    String? // Evidence PDF or photo proving rectification\n  status         String    @default(\"PENDING\") // PENDING, IN_PROGRESS, RESOLVED, VERIFIED\n  resolvedAt     DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  violation Violation @relation(fields: [violationId], references: [id], onDelete: Cascade)\n  assignee  User      @relation(\"AssignedActions\", fields: [assigneeId], references: [id])\n\n  @@map(\"corrective_actions\")\n}\n\nmodel AuditLog {\n  id           String   @id @default(uuid())\n  blockIndex   Int      @unique @default(autoincrement()) // Block height / sequence in blockchain\n  userId       String?\n  action       String // e.g. \"USER_LOGIN\", \"INSPECTION_REPORT_UPLOADED\", \"MINE_RESPONSE_SUBMITTED\"\n  entity       String // e.g. \"User\", \"Inspection\", \"Violation\", \"CorrectiveAction\"\n  entityId     String?\n  metadata     Json?\n  previousHash String   @db.VarChar(64) // SHA-256 hash of previous block\n  hash         String   @db.VarChar(64) // SHA-256 hash of current block\n  nonce        Int      @default(0) // Nonce for cryptographic hash uniqueness\n  timestamp    DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@map(\"audit_logs\")\n}\n",
